    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public {
        require(address(c).balance >= 100);
        uint256 beforeBal = address(c).balance;
        c.getFirstWithdrawalBonus(recipient); if (__ESBMC_reverted()) return;
        c.withdrawReward(recipient); if (__ESBMC_reverted()) return;
        assert(address(c).balance == beforeBal - 100);
    }

    receive() external payable {}
    fallback() external payable {}
}

